contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount, "not enough balance");

        // Precondition: c starts with zero balance
        uint balBefore = address(c).balance;
        require(balBefore == 0, "c must start with zero balance");

        // Record owner balance before (owner is a public getter)
        address owner = c.owner();
        uint ownerBalBefore = owner.balance;

        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule:
        // - If it reverted, c's balance is still 0 and owner balance unchanged.
        // - If it succeeded, c's balance is 0 and owner received exactly amount.
        if (reverted) {
            assert(address(c).balance == balBefore && owner.balance == ownerBalBefore);
        } else {
            assert(address(c).balance == 0 && owner.balance == ownerBalBefore + amount);
        }
    }

    receive() external payable {}
}

